# core_fx: last 50 uploads WITH views, so we can see which upload hours performed
CORE = """2026-11-02T18:03 2103729|2026-11-01T19:44 1366451|2026-10-31T17:55 844924|2026-10-30T02:23 538476|2026-10-29T02:10 12410832|2026-10-29T00:03 429109|2026-10-28T21:54 409751|2026-10-28T15:50 88178|2026-10-28T02:17 30754|2026-10-27T17:59 661367|2026-10-27T15:13 68514|2026-10-26T18:39 59165|2026-10-26T15:28 56109|2026-10-25T19:45 2759408|2026-10-25T15:05 2197043|2026-10-25T03:03 84170|2026-10-24T21:56 42921|2026-10-24T15:28 52446|2026-10-24T00:15 1092132|2026-10-23T15:13 96465|2026-10-23T00:57 66847|2026-10-22T17:16 3742824|2026-10-22T02:46 1537689|2026-10-21T14:07 92766|2026-10-20T22:56 46021|2026-10-19T20:30 3691176|2026-10-19T18:30 39382|2026-10-19T16:30 63066|2026-10-19T14:30 57703|2026-10-18T18:51 83157|2026-10-18T16:26 33341|2026-10-17T20:00 764492|2026-10-17T18:00 165540|2026-10-17T16:00 4286304|2026-10-17T14:00 436224|2026-10-16T22:00 33260|2026-10-16T20:00 107531|2026-10-16T18:00 76723|2026-10-16T16:00 274913|2026-10-16T14:00 201018|2026-10-15T18:11 71872"""

def parse(s):
    return [dt.datetime.fromisoformat(x) for x in s.split()]

def bucket(h):  # UTC hour -> label
    return f"{h:02d}-{(h+3)%24:02d}"

all_hours = collections.Counter()
wd = collections.Counter()
print("Per channel (UTC):")
for name, s in D.items():
    ts = parse(s)
    hrs = [t.hour + t.minute / 60 for t in ts]
    c = collections.Counter((t.hour // 3) * 3 for t in ts)
    top = ", ".join(f"{bucket(h)}h:{n}" for h, n in c.most_common(3))
    print(f"  {name:24s} median {int(statistics.median(hrs)):02d}:{int(statistics.median(hrs)%1*60):02d} UTC | busiest 3h windows: {top}")
    for t in ts:
        all_hours[t.hour] += 1
        wd[t.strftime('%a')] += 1
n = sum(all_hours.values())
print(f"\nAll {n} winning uploads by UTC hour:")
for h in range(24):
    print(f"  {h:02d}:00 UTC {'#' * all_hours[h]} {all_hours[h]}")
print("\nBy weekday:", ", ".join(f"{d}:{wd[d]}" for d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']))

print("\ncore_fx last 50 uploads: median views by UTC upload window")
rows = [(dt.datetime.fromisoformat(a.split()[0]), int(a.split()[1])) for a in CORE.split("|")]
g = collections.defaultdict(list)
for t, v in rows:
    g[(t.hour // 4) * 4].append(v)
for h in sorted(g):
    vs = g[h]
    print(f"  {h:02d}-{h+4:02d} UTC  n={len(vs):2d}  median {int(statistics.median(vs)):>9,}  hits>1M {sum(v > 1e6 for v in vs)}")
